package com.casecraft.service;
import com.casecraft.model.*; import com.casecraft.threads.*; import com.casecraft.repository.*; import com.casecraft.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.time.*; import java.util.concurrent.*;
@Service @Transactional
public class InvestigationService {
 private final CaseRepository cases; private final PersonRepository people; private final EvidenceRepository evidence; private final ClueRepository clues; private final StatementRepository statements; private final TimelineEventRepository events; private final ClueConnectionRepository connections;
 private final Set<String> uniqueEvidenceIds=new HashSet<>(); private final LinkedList<TimelineEvent> timelineCache=new LinkedList<>(); private final TreeSet<String> sortedRecordIndex=new TreeSet<>();
 public InvestigationService(CaseRepository c,PersonRepository p,EvidenceRepository e,ClueRepository cl,StatementRepository s,TimelineEventRepository t,ClueConnectionRepository cc){cases=c;people=p;evidence=e;clues=cl;statements=s;events=t;connections=cc;}
 public List<CaseFile> allCases(){return cases.findAll();} public CaseFile getCase(UUID id){return cases.findById(id).orElseThrow(()->new InvalidCaseException("Case not found: "+id));}
 public CaseFile createCase(Map<String,Object> body){String title=String.valueOf(body.getOrDefault("title","Untitled investigation")).trim(); if(title.isBlank())throw new InvalidCaseException("Case title is required"); CaseFile c=new CaseFile();c.setTitle(title);c.setSummary((String)body.getOrDefault("summary",""));c.setLocation((String)body.getOrDefault("location","Fictional location"));return cases.save(c);}
 public CaseFile updateCase(UUID id,Map<String,Object>b){CaseFile c=getCase(id);if(b.containsKey("title"))c.setTitle(String.valueOf(b.get("title")));if(b.containsKey("summary"))c.setSummary((String)b.get("summary"));if(b.containsKey("status"))c.setStatus(String.valueOf(b.get("status")));if(b.containsKey("location"))c.setLocation(String.valueOf(b.get("location")));return cases.save(c);}
 public void deleteCase(UUID id){cases.delete(getCase(id));}
 public Person addPerson(UUID id,Map<String,Object>b){CaseFile c=getCase(id);String role=String.valueOf(b.getOrDefault("role","WITNESS")).toUpperCase();String name=String.valueOf(b.getOrDefault("name","")).trim();if(name.isBlank())throw new InvalidCaseException("Person name is required");Person p=switch(role){case "DETECTIVE"->new Detective(c,name);case "SUSPECT"->new Suspect(c,name);case "VICTIM"->new Victim(c,name);default->new Witness(c,name);};p.setAge((String)b.get("age"));p.setOccupation((String)b.get("occupation"));p.setNotes((String)b.get("notes"));return people.save(p);}
 public Evidence addEvidence(UUID id,Map<String,Object>b){CaseFile c=getCase(id);String title=String.valueOf(b.getOrDefault("title","")).trim();if(title.isBlank())throw new InvalidCaseException("Evidence title is required");boolean added;synchronized(uniqueEvidenceIds){added=uniqueEvidenceIds.add(id+":"+title.toLowerCase());}if(evidence.existsByCaseFile_IdAndTitleIgnoreCase(id,title)||!added)throw new DuplicateEvidenceException("Evidence title already exists in this investigation");String type=String.valueOf(b.getOrDefault("type","PHYSICAL")).toUpperCase();Evidence e=switch(type){case "DIGITAL"->new DigitalEvidence(c,title,(String)b.get("description"));case "DOCUMENTARY"->new DocumentaryEvidence(c,title,(String)b.get("description"));case "TESTIMONIAL"->new TestimonialEvidence(c,title,(String)b.get("description"));default->new PhysicalEvidence(c,title,(String)b.get("description"));};e.setCategory(type);e.setReferenceUrl((String)b.get("referenceUrl"));try{return evidence.save(e);}catch(RuntimeException ex){uniqueEvidenceIds.remove(id+":"+title.toLowerCase());throw ex;}}
 public void deletePerson(UUID recordId){people.deleteById(recordId);} public void deleteEvidence(UUID recordId){Evidence e=evidence.findById(recordId).orElseThrow(()->new MissingEvidenceException("Evidence record not found"));synchronized(uniqueEvidenceIds){uniqueEvidenceIds.remove(e.getCaseFile().getId()+":"+e.getTitle().toLowerCase());}evidence.delete(e);} public void deleteClue(UUID recordId){clues.deleteById(recordId);} public void deleteStatement(UUID recordId){statements.deleteById(recordId);} public void deleteEvent(UUID recordId){events.deleteById(recordId);}
 public Evidence verifyEvidence(UUID evidenceId,boolean verified){Evidence e=evidence.findById(evidenceId).orElseThrow(()->new MissingEvidenceException("Evidence record not found"));e.setVerified(verified);return evidence.save(e);}
 public Clue addClue(UUID id,Map<String,Object>b){Clue c=new Clue();c.setCaseFile(getCase(id));c.setTitle(String.valueOf(b.getOrDefault("title","Untitled clue")));c.setDetail((String)b.get("detail"));c.setImportance(String.valueOf(b.getOrDefault("importance","MEDIUM")));return clues.save(c);}
 public ClueConnection connectClues(UUID sourceId,UUID targetId,String relationship){if(sourceId.equals(targetId))throw new InvalidCaseException("A clue cannot connect to itself");Clue a=clues.findById(sourceId).orElseThrow(()->new InvalidCaseException("Source clue not found"));Clue b=clues.findById(targetId).orElseThrow(()->new InvalidCaseException("Target clue not found"));if(!a.getCaseFile().getId().equals(b.getCaseFile().getId()))throw new InvalidCaseException("Clues must belong to the same case");ClueConnection c=new ClueConnection();c.setSource(a);c.setTarget(b);c.setRelationship(relationship==null?"RELATED_TO":relationship);return connections.save(c);}
 public Clue moveClue(UUID id,Map<String,Object>b){Clue c=clues.findById(id).orElseThrow(()->new InvalidCaseException("Clue not found"));if(b.get("x") instanceof Number n)c.setX(n.doubleValue());if(b.get("y") instanceof Number n)c.setY(n.doubleValue());return clues.save(c);}
 public Statement addStatement(UUID id,Map<String,Object>b){Statement s=new Statement();s.setCaseFile(getCase(id));s.setSpeaker(String.valueOf(b.getOrDefault("speaker","Unknown")));s.setContent(String.valueOf(b.getOrDefault("content","")));return statements.save(s);}
 public TimelineEvent addEvent(UUID id,Map<String,Object>b){TimelineEvent e=new TimelineEvent();e.setCaseFile(getCase(id));e.setDescription(String.valueOf(b.getOrDefault("description","Investigation event")));e.setLocation(String.valueOf(b.getOrDefault("location","Unknown")));e.setOccurredAt(b.get("occurredAt")!=null&&!String.valueOf(b.get("occurredAt")).isBlank()?LocalDateTime.parse(String.valueOf(b.get("occurredAt"))):LocalDateTime.now());TimelineEvent saved=events.save(e);synchronized(timelineCache){timelineCache.add(saved);timelineCache.sort(Comparator.comparing(TimelineEvent::getOccurredAt));}return saved;}
 public Map<String,Object> details(UUID id){CaseFile c=getCase(id);synchronized(sortedRecordIndex){sortedRecordIndex.add(c.getTitle());}List<Person> ps=people.findByCaseFile_Id(id);List<Evidence> es=evidence.findByCaseFile_Id(id);List<Clue> cs=clues.findByCaseFile_Id(id);List<Statement> ss=statements.findByCaseFile_Id(id);List<TimelineEvent> ts=events.findByCaseFile_Id(id).stream().sorted(Comparator.comparing(TimelineEvent::getOccurredAt)).toList();List<Map<String,Object>> links=connections.findBySource_CaseFile_IdOrTarget_CaseFile_Id(id,id).stream().map(x->Map.<String,Object>of("id",x.getId(),"sourceId",x.getSource().getId(),"targetId",x.getTarget().getId(),"relationship",x.getRelationship())).toList();return Map.of("case",caseDto(c),"people",ps.stream().map(this::personDto).toList(),"evidence",es.stream().map(this::evidenceDto).toList(),"clues",cs.stream().map(this::clueDto).toList(),"connections",links,"statements",ss.stream().map(this::statementDto).toList(),"events",ts.stream().map(this::eventDto).toList());}
 public Map<String,Object> caseDto(CaseFile c){return Map.of("id",c.getId(),"title",c.getTitle(),"summary",Objects.toString(c.getSummary(),""),"status",c.getStatus(),"location",Objects.toString(c.getLocation(),""),"createdAt",c.getCreatedAt(),"updatedAt",c.getUpdatedAt());}
 private Map<String,Object> personDto(Person p){return Map.of("id",p.getId(),"name",p.getName(),"role",p.getRole(),"age",Objects.toString(p.getAge(),""),"occupation",Objects.toString(p.getOccupation(),""),"notes",Objects.toString(p.getNotes(),""));}
 private Map<String,Object> evidenceDto(Evidence e){return Map.of("id",e.getId(),"title",e.getTitle(),"type",e.getEvidenceType(),"description",Objects.toString(e.getDescription(),""),"referenceUrl",Objects.toString(e.getReferenceUrl(),""),"verified",e.isVerified(),"collectedAt",e.getCollectedAt());}
 private Map<String,Object> clueDto(Clue c){return Map.of("id",c.getId(),"title",c.getTitle(),"detail",Objects.toString(c.getDetail(),""),"importance",c.getImportance(),"x",c.getX(),"y",c.getY());}
 private Map<String,Object> statementDto(Statement s){return Map.of("id",s.getId(),"speaker",s.getSpeaker(),"content",Objects.toString(s.getContent(),""),"recordedAt",s.getRecordedAt());}
 private Map<String,Object> eventDto(TimelineEvent e){return Map.of("id",e.getId(),"description",e.getDescription(),"location",Objects.toString(e.getLocation(),""),"occurredAt",e.getOccurredAt());}
 public Map<String,Object> analyze(UUID id){Map<String,Object>d=details(id);@SuppressWarnings("unchecked") List<Map<String,Object>> ss=(List<Map<String,Object>>)d.get("statements");@SuppressWarnings("unchecked") List<Map<String,Object>> ev=(List<Map<String,Object>>)d.get("evidence");ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<List<Map<String,Object>>> evidenceTask=pool.submit(new EvidenceAnalysisThread(ev));Future<List<Map<String,Object>>> statementTask=pool.submit(new StatementAnalysisThread(ss));List<Map<String,Object>> findings=new ArrayList<>();findings.addAll(evidenceTask.get());findings.addAll(statementTask.get());return Map.of("caseId",id,"findings",findings,"note","These are rule-based review prompts, not conclusions about guilt or truth.","analyzedAt",LocalDateTime.now());}catch(Exception ex){throw new RuntimeException("Analysis task failed",ex);}finally{pool.shutdown();}}
 public Map<String,Object> report(UUID id){Map<String,Object>d=details(id);Map<String,Object>analysis=analyze(id);ExecutorService pool=Executors.newSingleThreadExecutor();try{return pool.submit(new ReportGenerationThread(d,analysis)).get();}catch(Exception ex){throw new RuntimeException("Report generation failed",ex);}finally{pool.shutdown();}}
}
